window.questionsTimo2020 = [
  {n:1,skill:"Logical thinking",title:"Ashley and Amy's ages",en:"Ashley's age 5 years ago equals Amy's age 4 years later. When Ashley is 20, how old is Amy?\n(A) 11\n(B) 29\n(C) 19\n(D) 21",vi:"Tuổi Ashley 5 năm trước bằng tuổi Amy 4 năm sau. Khi Ashley 20 tuổi thì Amy bao nhiêu tuổi?\\n(A) 11\\n(B) 29\\n(C) 19\\n(D) 21",answer:"A",accepted:["a","11"],hint:"Compare both ages at the same point in time.",steps:["Ashley is 5 + 4 = 9 years older than Amy.","When Ashley is 20:","Amy = 20 - 9 = 11","Choose A."]},
  {n:2,skill:"Logical thinking",title:"Last day of April",en:"Today is Monday, 3 April. What day of the week is the last day of this month?\n(A) Monday\n(B) Saturday\n(C) Tuesday\n(D) Sunday",vi:"Hôm nay là thứ Hai, ngày 3 tháng Tư. Ngày cuối tháng là thứ mấy?\\n(A) Thứ Hai\\n(B) Thứ Bảy\\n(C) Thứ Ba\\n(D) Chủ nhật",answer:"D",accepted:["d","sunday","chủ nhật","chu nhat"],hint:"Count how many days there are from 3 April to 30 April, then divide by 7.",steps:["30 - 3 = 27 days later","27 = 3 weeks + 6 days","Six days after Monday is Sunday.","Choose D."]},
  {n:3,skill:"Logical thinking",title:"Repeating shapes",en:"The pattern repeats: triangle, square, circle, square. How many squares are in the first 28 shapes?\n(A) 15\n(B) 14\n(C) 8\n(D) 9",vi:"Dãy lặp lại tam giác, vuông, tròn, vuông. Trong 28 hình đầu có bao nhiêu hình vuông?\\n(A) 15\\n(B) 14\\n(C) 8\\n(D) 9",answer:"B",accepted:["b","14"],hint:"Each group of 4 shapes contains 2 squares.",steps:["28 ÷ 4 = 7 complete groups","Each group has 2 squares.","7 × 2 = 14","Choose B."]},
  {n:4,skill:"Logical thinking",title:"Powers of three",en:"Find the sum of the first 6 numbers in the pattern 1, 3, 9, 27, ...\n(A) 365\n(B) 360\n(C) 362\n(D) 364",vi:"Tính tổng 6 số đầu của dãy 1, 3, 9, 27, ...\\n(A) 365\\n(B) 360\\n(C) 362\\n(D) 364",answer:"D",accepted:["d","364"],hint:"Each term is 3 times the previous term.",steps:["First 6 terms: 1, 3, 9, 27, 81, 243","1 + 3 + 9 + 27 + 81 + 243 = 364","Choose D."]},
  {n:5,skill:"Logical thinking",title:"Thor's secret number",en:"Thor chose a 2-digit number with different digits. For 72, one digit is correct but in the wrong position. For 42, one digit is correct and in the correct position. What is Thor's number?\n(A) 74\n(B) 22\n(C) 47\n(D) 27",vi:"Dựa vào hai gợi ý về 72 và 42, tìm số có hai chữ số của Thor.\\n(A) 74\\n(B) 22\\n(C) 47\\n(D) 27",answer:"C",accepted:["c","47"],hint:"Test which digit in 42 can stay in its position without breaking the clue about 72.",steps:["The 4 in 42 is correct and stays in the tens place.","So 2 is not used.","From 72, 7 is correct but must move to the ones place.","The number is 47. Choose C."]},
  {n:6,skill:"Arithmetic",title:"Add and subtract",en:"Calculate 327 - 169 - 132 + 173 + 669.\n(A) 868\n(B) 968\n(C) 869\n(D) 768",vi:"Tính 327 − 169 − 132 + 173 + 669.\\n(A) 868\\n(B) 968\\n(C) 869\\n(D) 768",answer:"A",accepted:["a","868"],hint:"Group positive and negative numbers.",steps:["327 + 173 + 669 = 1169","169 + 132 = 301","1169 - 301 = 868","Choose A."]},
  {n:7,skill:"Arithmetic",title:"Sum from 11 to 20",en:"Find the sum of the 10 consecutive natural numbers from 11 to 20.\n(A) 105\n(B) 300\n(C) 310\n(D) 155",vi:"Tính tổng các số tự nhiên từ 11 đến 20.\\n(A) 105\\n(B) 300\\n(C) 310\\n(D) 155",answer:"D",accepted:["d","155"],hint:"Pair the first and last numbers.",steps:["11 + 20 = 31","12 + 19 = 31","There are 5 such pairs.","5 × 31 = 155","Choose D."]},
  {n:8,skill:"Arithmetic",title:"A long expression",en:"Calculate 36 × 42 - 4 × 9 × 17 - 15 × 36.\n(A) 360\n(B) 3600\n(C) 180\n(D) 350",vi:"Tính 36 × 42 − 4 × 9 × 17 − 15 × 36.\\n(A) 360\\n(B) 3600\\n(C) 180\\n(D) 350",answer:"A",accepted:["a","360"],hint:"Do all multiplications before subtraction.",steps:["36 × 42 = 1512","4 × 9 × 17 = 612","15 × 36 = 540","1512 - 612 - 540 = 360","Choose A."]},
  {n:9,skill:"Arithmetic",title:"Multiply by 1001",en:"Find 1001 × 123.\n(A) 123321\n(B) 123123\n(C) 321123\n(D) 321321",vi:"Tìm giá trị của 1001 × 123.\\n(A) 123321\\n(B) 123123\\n(C) 321123\\n(D) 321321",answer:"B",accepted:["b","123123"],hint:"Write 1001 as 1000 + 1.",steps:["123 × 1001 = 123 × 1000 + 123","= 123000 + 123","= 123123","Choose B."]},
  {n:10,skill:"Arithmetic",title:"Doubling sequence",en:"Find 1 + 2 + 4 + 8 + 16 + 32 + 64 + 128.\n(A) 255\n(B) 256\n(C) 254\n(D) 257",vi:"Tìm giá trị của 1 + 2 + 4 + 8 + 16 + 32 + 64 + 128.\\n(A) 255\\n(B) 256\\n(C) 254\\n(D) 257",answer:"A",accepted:["a","255"],hint:"The sum up to 128 is one less than the next power of 2.",steps:["The next doubled number is 256.","1 + 2 + 4 + ... + 128 = 256 - 1","= 255","Choose A."]},
  {n:11,skill:"Number theory",title:"Two-digit even numbers",en:"How many 2-digit even numbers are there?\n(A) 50\n(B) 45\n(C) 44\n(D) 49",vi:"Có bao nhiêu số chẵn có hai chữ số?\\n(A) 50\\n(B) 45\\n(C) 44\\n(D) 49",answer:"B",accepted:["b","45"],hint:"Count 10, 12, ..., 98.",steps:["The first is 10 and the last is 98.","(98 - 10) ÷ 2 + 1 = 45","Choose B."]},
  {n:12,skill:"Number theory",title:"A is twice B",en:"A + B = 60 and A is 2 times B. Find B.\n(A) 30\n(B) 40\n(C) 10\n(D) 20",vi:"A cộng B bằng 60 và A gấp đôi B. Tìm B.\\n(A) 30\\n(B) 40\\n(C) 10\\n(D) 20",answer:"D",accepted:["d","20"],hint:"The total contains 3 equal B-parts.",steps:["A = 2B","A + B = 3B = 60","B = 60 ÷ 3 = 20","Choose D."]},
  {n:13,skill:"Number theory",title:"Growing differences",en:"Find the next term: 1, 6, 16, 31, 51, 76, 106, ...\n(A) 111\n(B) 121\n(C) 131\n(D) 141",vi:"Tìm số tiếp theo trong dãy.\\n(A) 111\\n(B) 121\\n(C) 131\\n(D) 141",answer:"D",accepted:["d","141"],hint:"Look at the differences between neighbouring terms.",steps:["Differences: 5, 10, 15, 20, 25, 30","Next difference = 35","106 + 35 = 141","Choose D."]},
  {n:14,skill:"Number theory",title:"Phineas's marks",en:"Phineas and Ferb scored 162 altogether. Phineas scored 22 more than Ferb. What was Phineas's score?\n(A) 70\n(B) 90\n(C) 92\n(D) 72",vi:"Tổng điểm là 162 và Phineas hơn Ferb 22 điểm. Tìm điểm Phineas.\\n(A) 70\\n(B) 90\\n(C) 92\\n(D) 72",answer:"C",accepted:["c","92"],hint:"Remove the extra 22 marks, split equally, then put the extra back.",steps:["Equal part: (162 - 22) ÷ 2 = 70","Phineas: 70 + 22 = 92","Choose C."]},
  {n:15,skill:"Number theory",title:"A new operation",en:"Define a ⊕ b = a × b - b. Find 5 ⊕ 7.\n(A) 28\n(B) 30\n(C) 12\n(D) 35",vi:"Định nghĩa phép toán a ⊕ b = a × b − b. Hãy tìm giá trị của 5 ⊕ 7.\\n(A) 28\\n(B) 30\\n(C) 12\\n(D) 35",answer:"A",accepted:["a","28"],hint:"Replace a with 5 and b with 7.",steps:["5 ⊕ 7 = 5 × 7 - 7","= 35 - 7","= 28","Choose A."]},
  {n:16,skill:"Geometry",title:"Count line segments",en:"How many line segments are there in the figure?\n(A) 4\n(B) 6\n(C) 8\n(D) 9",vi:"Có bao nhiêu đoạn thẳng trong hình?\\n(A) 4\\n(B) 6\\n(C) 8\\n(D) 9",answer:"C",accepted:["c","8"],hint:"A straight line with three marked points contains two short segments and one longer segment.",steps:["Count the 3 segments along the base.","Count the 3 segments along the right sloping side.","Add the other 2 sloping segments.","3 + 3 + 2 = 8. Choose C."],image:"assets/fig-timo-2020-16.jpg"},
  {n:17,skill:"Geometry",title:"Count squares",en:"How many squares are there in the figure?\n(A) 4\n(B) 5\n(C) 6\n(D) 10",vi:"Có bao nhiêu hình vuông trong hình?\\n(A) 4\\n(B) 5\\n(C) 6\\n(D) 10",answer:"D",accepted:["d","10"],hint:"Count squares of every possible size, not only the smallest ones.",steps:["Count the small squares first.","Then count the larger squares made by joining small ones.","The systematic total is 10 squares.","Choose D."],image:"assets/fig-timo-2020-17.jpg"},
  {n:18,skill:"Geometry",title:"Parking lot perimeter",en:"A T-shaped parking lot is 90 m wide at the top, 30 m thick, and its stem extends 60 m. Find its perimeter.\n(A) 360\n(B) 280\n(C) 90\n(D) 450",vi:"Bãi đỗ xe hình chữ T có kích thước như hình. Tìm chu vi.\\n(A) 360\\n(B) 280\\n(C) 90\\n(D) 450",answer:"A",accepted:["a","360","360m"],unit:"m",hint:"The unknown horizontal pieces cancel with the width of the stem.",steps:["Top and lower horizontal pieces total 90 + 90 = 180 m.","Vertical pieces: 30 + 30 + 60 + 60 = 180 m.","Perimeter = 180 + 180 = 360 m","Choose A."],image:"assets/fig-timo-2020-18.jpg"},
  {n:19,skill:"Geometry",title:"Edges of a box",en:"A box has 8 vertices. How many edges does it have?\n(A) 6\n(B) 8\n(C) 9\n(D) 12",vi:"Một hình hộp có 8 đỉnh. Hình đó có bao nhiêu cạnh?\\n(A) 6\\n(B) 8\\n(C) 9\\n(D) 12",answer:"D",accepted:["d","12"],hint:"Count 4 top edges, 4 bottom edges and 4 joining edges.",steps:["Top face: 4 edges","Bottom face: 4 edges","Joining the faces: 4 edges","4 + 4 + 4 = 12. Choose D."],image:"assets/fig-timo-2020-19.jpg"},
  {n:20,skill:"Geometry",title:"Garden around a pool",en:"A square garden has perimeter 80 m. A square pool in its centre has perimeter 32 m. Find the shaded garden area outside the pool.\n(A) 336\n(B) 48\n(C) 400\n(D) 144",vi:"Tìm diện tích phần vườn bên ngoài hồ bơi hình vuông.\\n(A) 336\\n(B) 48\\n(C) 400\\n(D) 144",answer:"A",accepted:["a","336","336m2","336m²"],unit:"m²",hint:"Find each square's side from its perimeter.",steps:["Garden side: 80 ÷ 4 = 20 m","Garden area: 20 × 20 = 400 m²","Pool side: 32 ÷ 4 = 8 m","Pool area: 8 × 8 = 64 m²","Shaded area: 400 - 64 = 336 m². Choose A."],image:"assets/fig-timo-2020-20.jpg"},
  {n:21,skill:"Combinatorics",title:"Numbers without zero",en:"How many 2-digit numbers contain no digit 0?\n(A) 90\n(B) 80\n(C) 81\n(D) 91",vi:"Có bao nhiêu số có hai chữ số không chứa chữ số 0?\\n(A) 90\\n(B) 80\\n(C) 81\\n(D) 91",answer:"C",accepted:["c","81"],hint:"There are 9 choices for each place.",steps:["Tens digit: 1 to 9, so 9 choices","Ones digit: 1 to 9, so 9 choices","9 × 9 = 81","Choose C."]},
  {n:22,skill:"Combinatorics",title:"Candace's pens",en:"Candace and Phineas have 18 pens altogether. After Candace gives Phineas 4 pens, they have equal numbers. How many pens did Candace have originally?\n(A) 14\n(B) 11\n(C) 13\n(D) 22",vi:"Sau khi Candace cho Phineas 4 bút thì hai bạn bằng nhau. Ban đầu Candace có bao nhiêu bút?\\n(A) 14\\n(B) 11\\n(C) 13\\n(D) 22",answer:"C",accepted:["c","13"],hint:"After the transfer they each have half of 18.",steps:["After the transfer: 18 ÷ 2 = 9 pens each","Candace originally had 9 + 4 = 13 pens.","Choose C."]},
  {n:23,skill:"Combinatorics",title:"Paths from A to B",en:"On the grid, move only up or right from A to B. How many different paths are there?\n(A) 11\n(B) 8\n(C) 9\n(D) 10",vi:"Chỉ đi lên hoặc sang phải từ A đến B. Có bao nhiêu đường đi?\\n(A) 11\\n(B) 8\\n(C) 9\\n(D) 10",answer:"D",accepted:["d","10"],hint:"Every path uses 3 right moves and 2 up moves.",steps:["Each path has 5 moves: R, R, R, U, U.","Choose the 2 positions for the up moves.","5 × 4 ÷ 2 = 10 paths","Choose D."],image:"assets/fig-timo-2020-23.jpg"},
  {n:24,skill:"Combinatorics",title:"Eating six candies",en:"Sam has 6 candies. Each day she eats either 1 or 2 candies. In how many different ways can she eat all the candies?\n(A) 2\n(B) 10\n(C) 13\n(D) 9",vi:"Mỗi ngày Sam ăn 1 hoặc 2 viên. Có bao nhiêu cách ăn hết 6 viên?\\n(A) 2\\n(B) 10\\n(C) 13\\n(D) 9",answer:"C",accepted:["c","13"],hint:"The number of ways follows 1, 2, 3, 5, 8, 13.",steps:["Ways for 1 candy = 1; for 2 candies = 2.","Each new count is the sum of the previous two.","For 3, 4, 5, 6 candies: 3, 5, 8, 13.","Choose C."]},
  {n:25,skill:"Combinatorics",title:"Two-digit even numbers",en:"Choose 2 different digits from 0, 2, 4 and 6 to form 2-digit numbers. How many even numbers can be formed?\n(A) 8\n(B) 9\n(C) 6\n(D) 12",vi:"Dùng hai chữ số khác nhau từ 0, 2, 4, 6 để lập số chẵn có hai chữ số. Có bao nhiêu số?\\n(A) 8\\n(B) 9\\n(C) 6\\n(D) 12",answer:"B",accepted:["b","9"],hint:"The tens digit cannot be 0; every available units digit is even.",steps:["Tens digit: 3 choices (2, 4, 6)","Units digit: any of the 3 remaining digits","3 × 3 = 9 numbers","Choose B."]}
];
